// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address actor) public {
        // owner() reads the immutable-args block appended after the 4-byte selector.
        // Build calldata: selector(4) + 20-byte address + uint16 length(20).
        vm.assume(actor != address(0));

        bytes memory data = abi.encodePacked(c.owner.selector, actor, uint16(20));

        (bool ok, bytes memory ret) = address(c).call(data);

        assertTrue(ok && abi.decode(ret, (address)) == actor);
    }
}
